const sade = s => String(s).toLocaleLowerCase('tr').replace(/[çğıöşü]/g, c => ({ ç: 'c', ğ: 'g', ı: 'i', ö: 'o', ş: 's', ü: 'u' }[c]));
export const aksesuarGrubu = kimlik => AKSESUAR_KATALOG.find(a => a[0] === kimlik) || null;
// Katalogda arama: grup (boş: hepsi) ve yazı (ad, kod ya da ölçüde geçer)
export function aksesuarAra(grup = '', yazi = '') {
  const y = sade(yazi).trim();
  return AKSESUAR_KATALOG.filter(a => (!grup || a[1] === grup) && (!y || sade(a[2]).includes(y) || a[5].some(k => sade(k[0]).includes(y) || sade(k[2]).includes(y))));
}
// Projeye eklenecek kayıt. Katalog ürününde kalem sırası verilir; genel aksesuarda yalnız kimlik.
// { g: katalog kimliği, kod, ad, renk, adet, fiyat (birim satış), liste (liste fiyatı), hareket }
export function aksesuarKaydi(kimlik, sira = 0) {
  const genel = AKSESUAR_GENEL.find(a => a[0] === kimlik);
  if (genel) return { g: kimlik, kod: '', ad: genel[1], renk: '', adet: 1, fiyat: 0, liste: 0, hareket: '' };
  const a = aksesuarGrubu(kimlik), k = a?.[5][sira];
  if (!k) return null;
  return { g: kimlik, kod: k[0], ad: a[2] + (k[1] ? ' (' + k[1] + ')' : ''), renk: a[3][0] || '', adet: 1, fiyat: k[4], liste: k[4], hareket: a[4], olcu: k[2], genislik: k[3] };
}
// Kayıtlı aksesuar listesini güvenli biçime getirir (dosyadan açılan projeler için)
export function aksesuarListesi(p) {
  const metin = (v, n) => String(v ?? '').slice(0, n), sayi = (v, en) => { const x = Number(v); return Number.isFinite(x) && x >= 0 ? Math.min(x, en) : 0; };
  return (Array.isArray(p?.aksesuar) ? p.aksesuar : []).filter(x => x && typeof x === 'object').slice(0, 200).map(x => ({
    g: metin(x.g, 8), kod: metin(x.kod, 30), ad: metin(x.ad, 120) || 'Aksesuar', renk: metin(x.renk, 30), adet: Math.max(1, Math.round(sayi(x.adet, 999)) || 1),
    fiyat: sayi(x.fiyat, 1e8), liste: sayi(x.liste, 1e8), hareket: metin(x.hareket, 12), modul: x.modul ? metin(x.modul, 40) : '' }));
}
